import numpy as np

def advanced_matrix_ops():
    '''
    Load the previous session's matrix multiplication results from computation_cache.
    For each cached result, perform eigenvalue calculations using numpy.
    Returns:
        dict: {
            cache_key: {
                "matrix": <2D list>,
                "eigenvalues": <list>,
                "eigenvectors": <2D list>
            },
            ...
        }
    If no cache exists, demonstrates with a default example.
    '''
    global computation_cache
    results = {}

    # Step 1: If computation_cache has entries, use them
    if computation_cache:
        for cache_key, matrix in computation_cache.items():
            try:
                eigenvalues, eigenvectors = np.linalg.eig(np.array(matrix))
                results[cache_key] = {
                    "matrix": matrix,
                    "eigenvalues": eigenvalues.tolist(),
                    "eigenvectors": eigenvectors.tolist()
                }
            except Exception as e:
                results[cache_key] = str(e)
        return results
    else:
        # Step 2: Demonstrate on a default example if cache is empty
        demo_A = [[5, 4], [2, 1]]
        eigenvalues, eigenvectors = np.linalg.eig(np.array(demo_A))
        return {
            "demo": {
                "matrix": demo_A,
                "eigenvalues": eigenvalues.tolist(),
                "eigenvectors": eigenvectors.tolist()
            }
        }

